\node[squarednode, text width=10cm,align=center]      (Main_Theorem)                              {\textbf{Theorem \ref{thm:GreedyMin-max}:} Algorithm \ref{alg:LocalMin-max} converges in polynomial time to a point $(x^\star, y^\star)$ which is a greedy adversarial equilibrium.};



\node[squarednode,text width=8.4cm,align=center]      (Lemma_3)       [below=of Main_Theorem] {\textbf{Lemma \ref{Lemma_SharedLM}:}  If Props. \ref{Prop_lower_bound}-\ref{prop_SGVariance} hold for an approximate local minimizer $x^\star$ of $\mathfrak{h}_{\eps, \sigma}(\cdot, y^\star)$, the $x^\star$ is also an approximate local minimizer of $\mathfrak{g}_{\eps, \sigma}(\cdot, y^\star)$.};
\node[squarednode, text width=3cm,align=center]      (Lemma_2)       [right=of Lemma_3, xshift=-0.2cm] {\textbf{Lemma \ref{lemma:Player2}:} $y^\star$ is an approximate local minimizer of $f(x^\star, \cdot)$};
\node[squarednode, text width=3cm,align=center]      (Lemma_1)       [left=of Lemma_3, xshift=0cm] {\textbf{Lemma \ref{lemma:RunningTime}:} Algorithm \ref{alg:LocalMin-max} converges in polynomial time.};



\node[squarednode, text width=3cm,align=center]      (Prop_8)       [below=of Lemma_3, xshift=-3cm, yshift=-1.5cm] {\textbf{Prop. \ref{prop_SGVariance}:} Stochastic gradient has low variance at $(x^\star, y^\star)$.};
\node[squarednode,text width=3cm,align=center]      (Prop_9)       [right=of Prop_8,xshift=1cm, yshift=1.5cm] {\textbf{Prop. \ref{Prop_first_order_x}:} $x^\star$ is a 1st-order stationary point of $\mathfrak{h}_{\eps, \sigma}^{x^\star}(\cdot, y^\star)$.};
\node[squarednode, text width= 3cm,align=center]      (Prop_10)       [right=of Prop_9,xshift=-0.6cm, yshift= -1.5cm] {\textbf{Prop. \ref{Prop_NoisySGD}:} $x^\star$ satisfies 2nd-order condition to be an approximate local minimizer of $\mathfrak{h}_{\eps, \sigma}^{x^\star}(\cdot, y^\star)$};


\node[squarednode,text width=4cm,align=center]      (Prop_4)       [below=of Prop_8,  yshift=-3.5cm] {\textbf{Prop. \ref{Lemma_Greedypath}:} Algorithm \ref{alg:InnerMaxLoop} computes a greedy path.};
\node[squarednode, text width=6cm,align=center]      (Prop_6)       [right=of Prop_4, xshift=-2cm,  yshift=3.5cm] {\textbf{Prop. \ref{Prop_fixed_point}:} fixed point property: $h(x^\star, y^\star) = g_\eps(x^\star, y^\star) = f(x^\star, y^\star)$};
\node[squarednode, text width=3cm,align=center]      (Prop_5)       [left=of Prop_4,  xshift=1.8cm, yshift=3.5cm] {\textbf{Prop. \ref{Prop_lower_bound}:} $h_\eps$ is a lower bound for greedy max function.};
\node[squarednode, text width=5cm,align=center]      (Prop_7)       [right=of Prop_4, xshift=2cm,  yshift=1cm] {\textbf{Prop. \ref{lemma_SG}:} $\Gamma_k$ is a stochastic gradient for $\mathfrak{h}_{\eps, \sigma}^{x^\star}(\cdot, y^\star)$};


