\caption{A diagram of the proof of the main theorem.  A black arrow means that a lemma or proposition was used to prove another lemma, proposition or theorem.  The blue arrows pointing from propositions \ref{Prop_lower_bound}-\ref{Prop_NoisySGD} to Lemma \ref{Lemma_SharedLM} mean that those propositions were used to satisfy the conditions of Lemma \ref{Lemma_SharedLM}.}\label{fig:proof_diagram}
\end{figure}

